== java/net/officefloor/hq/app/rate/ValidateRate.java
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: the grade is one of A, B or C,
 *  the rate a percent 0.00 or more with up to two decimals, the from-date (optional) a real yyyy-mm-dd date. */
public class ValidateRate {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@PathVariable("grade") String grade, @RequestBody RateRequest request,
            Out<RateInput> body) throws InvalidRateException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidRateException("Sign in before changing rates.");
        }
        String g = grade == null ? "" : grade.trim();
        if (!GRADES.contains(g)) {
            throw new InvalidRateException("The grade must be A, B or C.");
        }
        String rate = request.rate() == null ? "" : request.rate().trim();
        if (!rate.matches("\\d{1,3}(\\.\\d{1,2})?")) {
            throw new InvalidRateException("The rate must be a percent, 0.00 to 999.99, with up to two decimals.");
        }
        String fromText = request.from() == null ? "" : request.from().trim();
        LocalDate from = null;
        if (!fromText.isEmpty()) {
            try {
                from = LocalDate.parse(fromText);
            } catch (DateTimeParseException e) {
                throw new InvalidRateException("The from-date must be a date, yyyy-mm-dd.");
            }
        }
        body.set(new RateInput(request.user().trim(), g, new BigDecimal(rate).setScale(2), from));
    }
}
-- The sheet's rate for each grade: a percent with two decimals. A grade with no row has no rate.
CREATE TABLE rate (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet(id),
    grade    CHAR(1)      NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    pct      DECIMAL(5, 2) NOT NULL CHECK (pct >= 0),
    PRIMARY KEY (sheet_id, grade)
);
-- A rate may carry a from-date: a grade may have several rates, one per from-date (and at most one
-- with none, which applies from the beginning of time). A claim uses the rate whose from-date is the
-- latest on or before its date.
ALTER TABLE rate DROP PRIMARY KEY;
ALTER TABLE rate ADD COLUMN from_date DATE;
CREATE INDEX rate_sheet_grade ON rate (sheet_id, grade);
-- A person's statements: how many have been taken, and the last one's due-total (NULL when it was n/a,
-- or none was taken) and date (the sheet's today when it was taken; NULL when none was taken).
ALTER TABLE person ADD COLUMN statement_count INT DEFAULT 0 NOT NULL;
ALTER TABLE person ADD COLUMN stated_total DECIMAL(14, 2);
ALTER TABLE person ADD COLUMN statement_date DATE;
-- Whether a claim is bound by its person's last statement (it counted then), and the figure it was bound
-- to (NULL when its figure was n/a then: its due stays live). The person's next statement rebinds or unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(14, 2);

